const originalRender=render;
function navigateTo(next){view=next;render()}
function islandInfo(w){$('#gamebody').innerHTML=`<div class="eyebrow">VÙNG ĐẤT SẮP RA MẮT</div><h2>${worlds[w][2]} ${worlds[w][0]}</h2><p>${worlds[w][1]}</p><p>${w===2?'Những chú robot đang chuẩn bị thử thách sắp xếp lệnh và sửa thuật toán.':'Những vụ án nhỏ sẽ giúp em học cách so sánh bằng chứng và phát hiện mâu thuẫn.'}</p><div class="tutor">Hòn đảo này đang được xây dựng. Em có thể khám phá Rừng Quy Luật và Lâu Đài Suy Luận ngay hôm nay!</div><button class="btn" onclick="document.querySelector('#game').close();play(0)">Khám phá Rừng Quy Luật →</button>`;$('#game').showModal()}
render=function(){originalRender();document.body.classList.toggle('island-mode',view==='map');if(view!=='map')return;$('#content').innerHTML=`<section class="gameworld" aria-label="Bản đồ bốn hòn đảo tư duy"><div class="mapviewport" tabindex="0" aria-label="Bản đồ có thể cuộn ngang trên điện thoại"><div class="mapcanvas"><div class="map-heading"><span>CHÀO MỪNG ĐẾN VỚI</span><h1>Quần đảo tư duy</h1><p>Cùng Cáo thắp lại hải đăng · 6–8 tuổi</p></div>${worlds.map((w,i)=>animatedIslandMarkup(w,i)).join('')}<span class="map-spark spark-one">✧</span><span class="map-spark spark-two">✦</span></div></div><div class="game-topbar"><div class="player-card"><span class="player-face">🦊</span><div><b>Nhà thám hiểm nhỏ</b><small>${state.age} tuổi · ${state.completed.length}/10 nhiệm vụ</small><span class="xp-track"><i style="width:${state.completed.length/10*100}%"></i></span></div></div><div class="game-resources"><span>⭐ <b>${stars()}</b> <small>sao</small></span><span>🧭 <b>${state.completed.length}</b><small>/ 10 khám phá</small></span></div><button class="round-game-btn" onclick="navigateTo('parent')" aria-label="Góc phụ huynh">⚙</button></div><div class="quest-note"><span>📜</span><div><b>Giải cứu Đảo Ánh Sáng</b><small>${state.completed.length===10?'Em đã khám phá mọi thử thách!':'Tìm những viên sáng để thắp lại hải đăng.'}</small></div></div><div class="game-bottom"><div class="game-logo">Logic<span>Quest</span><small>PHIÊU LƯU TƯ DUY</small></div><nav class="game-dock" aria-label="Điều hướng trò chơi"><button class="selected" onclick="navigateTo('map')"><span>🏝️</span>Bản đồ</button><button onclick="navigateTo('progress')"><span>🧭</span>Hành trình</button><button onclick="navigateTo('badges')"><span>🏆</span>Huy hiệu</button><button onclick="navigateTo('parent')"><span>🏡</span>Phụ huynh</button></nav><button class="owl-help" onclick="mapHelp()" aria-label="Hướng dẫn chơi"><span>🦉</span><b>Cú Mèo</b></button></div><div class="mobile-map-tip">↔ Vuốt ngang để khám phá các đảo</div><button class="motion-toggle" onclick="toggleMapMotion()" aria-pressed="false">⏸ Dừng chuyển động</button></section>`;initIslandMotion();};
function mapHelp(){$('#gamebody').innerHTML='<div class="eyebrow">CÚ MÈO ĐỒNG HÀNH</div><h2>Chào nhà thám hiểm! 🦉</h2><p>Bấm vào hòn đảo hoặc đường viền sáng để bắt đầu chơi. Quan sát câu đố, chọn đáp án và bấm kiểm tra.</p><p>Mỗi nhiệm vụ có một gợi ý. Em luôn nhận được một sao khi hoàn thành lần đầu, kể cả khi cần gợi ý. Với ý tưởng mở, em có thể nhờ người lớn ghi lời kể.</p><p>Bốn hòn đảo có 10 nhiệm vụ: tìm manh mối, khám phá quy luật, nghĩ cách mới, lập kế hoạch và thử cách khác. Tiến độ được lưu trên trình duyệt này.</p><button class="btn" onclick="document.querySelector(\'#game\').close()">Mình hiểu rồi!</button>';$('#game').showModal()}
render();
